def getHappyString(n: int, k: int) -> str:
    def backtrack(current):
        if len(current) == n:
            results.append("".join(current))
            return

        for char in ['a', 'b', 'c']:
            if not current or current[-1] != char:
                current.append(char)
                backtrack(current)
                current.pop()

    results = []
    backtrack([])

    if k > len(results):
        return ""
    return results[k - 1]
